// 농장별 API 키를 env 에서 global 로 (2026-08-29, B2).
// ecosystem.config.js 가 /home/lhk/smartfarm/.sensor-api-key 를 SENSOR_API_KEY 로 주입한다.
// global.get('sensorApiKey') 를 쓰는 함수들이 이 값을 받는다. 없으면 경고만 — 공통 키로 폴백하지 않는다.
const key = env.get('SENSOR_API_KEY');
if (key && key.length >= 32) {
    global.set('sensorApiKey', key);
    node.status({ fill: 'green', shape: 'dot', text: '농장 키 ' + key.slice(0, 6) + '…' });
} else {
    global.set('sensorApiKey', null);
    node.warn('SENSOR_API_KEY 없음 — .sensor-api-key 파일과 ecosystem 확인 (장비코드 setup 미완?)');
    node.status({ fill: 'red', shape: 'ring', text: '농장 키 없음' });
}
return null;
